    _INPUT : pipe2py.modules pipe like object (iterable of items)
    conf : {'path': {'value': <element path>}}

    Yields
    ------
    _OUTPUT : items
    """
    path = DotDict(conf).get('path', **kwargs)

    for item in _INPUT:
