                    if r.xpath('.//w:rPr/w:rStyle[@w:val="%s"]' % self.style, namespaces=self.namespaces):
                        xsl += text
                        if xsl_r is None and text:
                            xsl_r = r
                        else:
                            r.getparent().remove(r)
                    elif text:
