def log_task(
    task, logger=logging, level='info', propagate_fail=True, uuid=None
):
    """
    Parameterized decorator to wrap a function in a log task

    Example:
        >>> @log_task('mytask')
        ... def do_something():
        ...     pass
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            with LogTask(
                task,
                logger=logger,
                level=level,
                propagate_fail=propagate_fail,
                uuid=uuid
            ):
                return func(*args, **kwargs)

        return wrapper

    return decorator

