def getEdges(self, vertex, inEdges = True, outEdges = True, rawResults = False) :
        """returns in, out, or both edges liked to a given document. vertex can be either a Document object or a string for an _id.
        If rawResults a arango results will be return as fetched, if false, will return a liste of Edge objects"""
        if isinstance(vertex, Document):
            vId = vertex._id
        elif (type(vertex) is str) or (type(vertex) is bytes):
            vId = vertex
        else :
            raise ValueError("Vertex is neither a Document nor a String")

        params = {"vertex" : vId}
        if inEdges and outEdges :
            pass
        elif inEdges :
            params["direction"] = "in"
        elif outEdges :
            params["direction"] = "out"
        else :
            raise ValueError("inEdges, outEdges or both must have a boolean value")

        r = self.connection.session.get(self.edgesURL, params = params)
        data = r.json()
        if r.status_code == 200 :
            if not rawResults :
                ret = []
                for e in data["edges"] :
                    ret.append(Edge(self, e))
                return ret
            else :
                return data["edges"]
        else :
            raise CreationError("Unable to return edges for vertex: %s" % vId, data)

def ins2dict(ins, kind=''):
    """Turn a SQLAlchemy Model instance to dict.

    :param ins: a SQLAlchemy instance.
    :param kind: specify which kind of dict tranformer should be called.
    :return: dict, instance data.

    If model has defined `to_xxx_dict`, then ins2dict(ins, 'xxx') will
    call `model.to_xxx_dict()`. Default kind is ''.

    If model not defined 'to_dict', then ins2dict will transform according
    by model column definition.
    """
    if kind and hasattr(ins, 'to_%s_dict' % kind):
        return getattr(ins, 'to_%s_dict' % kind)()
    elif hasattr(ins, 'to_dict'):
        return getattr(ins, 'to_dict')()
    else:
        return _turn_row_to_dict(ins)

def get_wireframe(viewer, x, y, z, **kwargs):
    """Produce a compound object of paths implementing a wireframe.
    x, y, z are expected to be 2D arrays of points making up the mesh.
    """
    # TODO: something like this would make a great utility function
    # for ginga
    n, m = x.shape
    objs = []
    for i in range(n):
        pts = np.asarray([(x[i][j], y[i][j], z[i][j])
                          for j in range(m)])
        objs.append(viewer.dc.Path(pts, **kwargs))

    for j in range(m):
        pts = np.asarray([(x[i][j], y[i][j], z[i][j])
                          for i in range(n)])
        objs.append(viewer.dc.Path(pts, **kwargs))

    return viewer.dc.CompoundObject(*objs)

def set_admin(msg, handler):
    """Handle admin verification responses from NickServ.

    | If NickServ tells us that the nick is authed, mark it as verified.

    """
    if handler.config['feature']['servicestype'] == "ircservices":
        match = re.match("STATUS (.*) ([0-3])", msg)
    elif handler.config['feature']['servicestype'] == "atheme":
        match = re.match("(.*) ACC ([0-3])", msg)
    if match:
        status = int(match.group(2))
        nick = match.group(1)
        if status != 3:
            return
        with handler.db.session_scope() as session:
            admin = session.query(Permissions).filter(Permissions.nick == nick).first()
            if admin is None:
                session.add(Permissions(nick=nick, role='admin', registered=True, time=datetime.now()))
            else:
                admin.registered = True
                admin.time = datetime.now()

