def creatauth(name, homedir):
    """ Function create user in linux for group and set homedir. Function return gid and uid."""

    uid, gid = [None, None]
    # get information about user
    command = "id %s" % (name)
    data = commands.getstatusoutput(command)

    if data[0] > 0:
        # create new system user
        command = "useradd -g %s %s" % (sett.APACHEIIS_GROUP, name)
        #command = "useradd -g %s %s" % ("www-data",name)
        data = commands.getstatusoutput(command)
        if data[0] != 0:
            msg = "Error: Can't create user."
            sys.stderr.write(msg)

    # set homedir for user
    command = "usermod -d %s %s" % (homedir, name)
    data = commands.getstatusoutput(command)

    command = "chown %s:%s %s -R" % (name, sett.APACHEIIS_GROUP, homedir)
    data = commands.getstatusoutput(command)

    # get information about user
    command = "id %s" % (name)
    data = commands.getstatusoutput(command)

    # check new user and get uid, gid
    if data[0] > 0:
        msg = "Error: User not create."
        sys.stderr.write(msg)
    else:
        for it in data[1].split(" "):
            m = re.search('uid=([0-9]*)', it)
            try:
                uid = m.group(1)
            except:
                pass

            m = re.search('gid=([0-9]*)', it)
            try:
                gid = m.group(1)
            except:
                pass

        return {"uid": uid, "gid": gid}
    return {}

def get_command_response_from_cache(self, device_id, command, command2):
        """Gets response"""
        key = self.create_key_from_command(command, command2)
        command_cache = self.get_cache_from_file(device_id)

        if device_id not in command_cache:
            command_cache[device_id] = {}
            return False
        elif key not in command_cache[device_id]:
            return False

        response = command_cache[device_id][key]
        expired = False
        if response['ttl'] < int(time()):
            self.logger.info("cache expired for device %s", device_id)
            expired = True

            if os.path.exists(LOCK_FILE):
                self.logger.info("cache locked - will wait to rebuild %s", device_id)
            else:
                self.logger.info("cache unlocked - will rebuild %s", device_id)
                newpid = os.fork()
                if newpid == 0:
                    self.rebuild_cache(device_id, command, command2)

        if expired:
            self.logger.info("returning expired cached device status %s", device_id)
        else:
            self.logger.info("returning unexpired cached device status %s", device_id)

        return response['response']

